    question: "$a + \\frac{1}{a} = \\sqrt{6}$ হলে, $a^3 + \\frac{1}{a^3}$ এর মান কত?",
    solution: `
      দেওয়া আছে, $a + \\frac{1}{a} = \\sqrt{6}$<br><br>
      প্রদত্ত রাশি $= a^3 + \\frac{1}{a^3}$<br>
      $= \\left(a + \\frac{1}{a}\\right)^3 - 3 \\cdot a \\cdot \\frac{1}{a}\\left(a + \\frac{1}{a}\\right)$<br>
      $= (\\sqrt{6})^3 - 3\\sqrt{6}$<br>
      $= 6\\sqrt{6} - 3\\sqrt{6}$<br>
      $= 3\\sqrt{6}$<br><br>
      <b>উত্তর:</b> $3\\sqrt{6}$
    `
