    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "একটি ছাগল ৮% ক্ষতিতে বিক্রয় করা হলো। ছাগলটি আরও ৮০০ টাকা বেশি মূল্যে বিক্রয় করলে ৮% লাভ হতো। ছাগলটির ক্রয়মূল্য নির্ণয় কর।",
    solution: `
      মনে করি, ছাগলটির ক্রয়মূল্য ১০০ টাকা<br><br>
      ৮% ক্ষতিতে বিক্রয়মূল্য = $(১০০ - ৮) = ৯২$ টাকা<br>
      ৮% লাভে বিক্রয়মূল্য = $(১০০ + ৮) = ১০৮$ টাকা<br><br>
      বিক্রয়মূল্যের পার্থক্য = $(১০৮ - ৯২) = ১৬$ টাকা<br><br>
      বিক্রয়মূল্যের পার্থক্য ১৬ টাকা হলে ক্রয়মূল্য ১০০ টাকা<br>
      $\\therefore$ বিক্রয়মূল্যের পার্থক্য ১ টাকা হলে ক্রয়মূল্য = $\\frac{১০০}{১৬}$ টাকা<br>
      $\\therefore$ বিক্রয়মূল্যের পার্থক্য ৮০০ টাকা হলে ক্রয়মূল্য = $\\frac{১০০ \\times ৮০০}{১৬} = ৫,০০০$ টাকা<br><br>
      <b>উত্তর:</b> ৫,০০০ টাকা।
    `
