    source: "ঔষধ প্রশাসন অধিদপ্তর",
    examYear: "২০২৪",
    question: "সরল করুন: $\\frac{a}{3} + \\frac{a}{6} - \\frac{3a}{8}$",
    solution: `
      প্রদত্ত রাশি = $\\frac{a}{3} + \\frac{a}{6} - \\frac{3a}{8}$<br><br>
      এখানে ৩, ৬ ও ৮ এর ল.সা.গু = ২৪<br><br>
      $= \\frac{8a + 4a - 3 \\times 3a}{24}$<br>
      $= \\frac{12a - 9a}{24}$<br>
      $= \\frac{3a}{24}$<br>
      $= \\frac{a}{8}$<br><br>
      <b>উত্তর:</b> $\\frac{a}{8}$
    `
