    question: "$a + \\frac{1}{a} = 7$ হলে, $a^3 + \\frac{1}{a^3}$ এর মান কত?",
    solution: `
      দেওয়া আছে, $a + \\frac{1}{a} = 7$<br><br>
      প্রদত্ত রাশি $= a^3 + \\frac{1}{a^3}$<br>
      $= \\left(a + \\frac{1}{a}\\right)^3 - 3 \\cdot a \\cdot \\frac{1}{a} \\left(a + \\frac{1}{a}\\right)$<br>
      $= (7)^3 - 3(7)$<br>
      $= 343 - 21$<br>
      $= 322$<br><br>
      <b>উত্তর:</b> 322
    `
