    question: "উৎপাদকে বিশ্লেষণ করুন: $4x^2 + 5x - 6$",
    solution: `
      প্রদত্ত রাশি = $4x^2 + 5x - 6$<br>
      $= 4x^2 + 8x - 3x - 6$<br>
      $= 4x(x + 2) - 3(x + 2)$<br>
      $= (x + 2)(4x - 3)$<br><br>
      <b>উত্তর:</b> $(x + 2)(4x - 3)$
    `
