    examYear: "২০২৪",
    question: "ক্রয়মূল্যের উপর শতকরা ২৫% বেশি মূল্য তালিকায় ধার্য করা থাকলে শতকরা কত লাভ বা ক্ষতি হতো?",
    solution: `
      মনে করি, ক্রয়মূল্য = ১০০ টাকা<br><br>
      ক্রয়মূল্যের উপর ২৫% বেশিতে ধার্যমূল্য (তালিকা মূল্য) = $(১০০ + ২৫) = ১২৫$ টাকা<br><br>
      ১০% কমিশনে ছাড়ের পরিমাণ = $১২৫$ এর ১০% = $১২৫ \\times \\frac{১০}{১০০} = ১২.৫$ টাকা<br><br>
      $\\therefore$ বিক্রয়মূল্য = $(১২৫ - ১২.৫) = ১১২.৫$ টাকা<br><br>
      $\\therefore$ লাভ = বিক্রয়মূল্য - ক্রয়মূল্য<br>
      $= (১১২.৫ - ১০০) = ১২.৫$ টাকা<br><br>
      <b>উত্তর:</b> ১২.৫% লাভ।
    `
