    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "পিতা ও পুত্রের বর্তমান বয়সের সমষ্টি ৬৫ বছর। ১০ বছর পূর্বে পিতার বয়স পুত্রের বয়সের দ্বিগুণ ছিল। ১০ বছর পর প্রত্যেকের বয়স কত হবে?",
    solution: `
      মনে করি,<br>
      পুত্রের বর্তমান বয়স = $x$ বছর<br>
      $\\therefore$ পিতার বর্তমান বয়স = $(৬৫ - x)$ বছর<br><br>
      প্রশ্নমতে,<br>
      $(৬৫ - x) - ১০ = ২(x - ১০)$<br>
      $\\Rightarrow ৫৫ - x = ২x - ২০$<br>
      $\\Rightarrow ৩x = ৭৫$<br>
      $\\therefore x = ২৫$<br><br>
      $\\therefore$ পুত্রের বর্তমান বয়স = ২৫ বছর এবং পিতার বর্তমান বয়স = $(৬৫ - ২৫) = ৪০$ বছর।<br><br>
      $\\therefore$ ১০ বছর পর পুত্রের বয়স হবে = $(২৫ + ১০) = ৩৫$ বছর<br>
      এবং ১০ বছর পর পিতার বয়স হবে = $(৪০ + ১০) = ৫০$ বছর।<br><br>
      <b>উত্তর:</b> পিতার বয়স ৫০ বছর ও পুত্রের বয়স ৩৫ বছর।
    `
