    solution: `
      ২৫ গ্রাম গহনায়,<br>
      সোনার পরিমাণ = $২৫ \\times \\frac{৩}{৫} = ১৫$ গ্রাম<br>
      তামার পরিমাণ = $২৫ \\times \\frac{২}{৫} = ১০$ গ্রাম<br><br>
      মনে করি, $x$ গ্রাম সোনা মেশাতে হবে।<br><br>
      প্রশ্নমতে,<br>
      $\\frac{১৫ + x}{১০} = \\frac{৫}{১}$<br>
      $\\Rightarrow ১৫ + x = ৫০$<br>
      $\\Rightarrow x = ৫০ - ১৫$<br>
      $\\therefore x = ৩৫$<br><br>
      <b>উত্তর:</b> ৩৫ গ্রাম।
    `
