    solution: `
      প্রদত্ত রাশি = $x^4 - 7x^2 + 1$<br>
      $= (x^2)^2 + 2 \\cdot x^2 \\cdot 1 + 1^2 - 9x^2$<br>
      $= (x^2 + 1)^2 - (3x)^2$<br>
      $= (x^2 + 1 + 3x)(x^2 + 1 - 3x)$<br>
      $= (x^2 + 3x + 1)(x^2 - 3x + 1)$<br><br>
      <b>উত্তর:</b> $(x^2 + 3x + 1)(x^2 - 3x + 1)$
    `
