    question: "১৪ জন লোক একটি কাজ ১৫ দিনে শেষ করতে পারে। ঐ কাজটি ১০ দিনে করতে হলে কত জন লোক নিয়োগ করতে হবে?",
    solution: `
      ১৫ দিনে কাজটি করতে পারে = ১৪ জন লোক<br>
      $\\therefore$ ১ দিনে কাজটি করতে পারে = $(১৪ \\times ১৫)$ জন লোক<br>
      $\\therefore$ ১০ দিনে কাজটি করতে পারে = $\\frac{১৪ \\times ১৫}{১০} = ২১$ জন লোক।<br><br>
      <b>উত্তর:</b> ২১ জন।
    `
