    solution: `
      দেওয়া আছে, বর্গক্ষেত্রের এক বাহুর দৈর্ঘ্য = ৩০০ মিটার<br>
      $\\therefore$ বর্গক্ষেত্রের ক্ষেত্রফল = $(৩০০)^২ = ৯০,০০০$ বর্গমিটার<br><br>
      রাস্তাসহ বর্গক্ষেত্রের এক বাহুর দৈর্ঘ্য = $(৩০০ + ২ \\times ৪) = (৩০০ + ৮) = ৩০৮$ মিটার<br>
      $\\therefore$ রাস্তাসহ বর্গক্ষেত্রের ক্ষেত্রফল = $(৩০৮)^২ = ৯৪,৮৬৪$ বর্গমিটার<br><br>
      $\\therefore$ রাস্তার ক্ষেত্রফল = (রাস্তাসহ ক্ষেত্রফল - মূল বর্গক্ষেত্রের ক্ষেত্রফল)<br>
      $= (৯৪,৮৬৪ - ৯০,০০০) = ৪,৮৬৪$ বর্গমিটার।<br><br>
      <b>উত্তর:</b> ৪,৮৬৪ বর্গমিটার।
    `
