    examYear: "২০২৪",
    question: "উৎপাদকে বিশ্লেষণ করুন: $x^2 + 13x + 36$",
    solution: `
      প্রদত্ত রাশি = $x^2 + 13x + 36$<br>
      $= x^2 + 9x + 4x + 36$<br>
      $= x(x + 9) + 4(x + 9)$<br>
      $= (x + 9)(x + 4)$<br><br>
      <b>উত্তর:</b> $(x + 9)(x + 4)$
    `
