    question: "একটি ত্রিভুজাকৃতির জমির ভূমি ৭৫ ফুট এবং উচ্চতা ৪৪ ফুট। প্রতি বর্গফুট ২৩.৫০ টাকা হিসেবে ঘাস লাগাতে কত টাকা খরচ হবে?",
    solution: `
      দেওয়া আছে,<br>
      ত্রিভুজের ভূমি = ৭৫ ফুট এবং উচ্চতা = ৪৪ ফুট<br><br>
      আমরা জানি,<br>
      ত্রিভুজের ক্ষেত্রফল = $\\frac{১}{২} \\times \\text{ভূমি} \\times \\text{উচ্চতা}$<br>
      $= \\frac{১}{২} \\times ৭৫ \\times ৪৪ = ১৬৫০$ বর্গফুট<br><br>
      ১ বর্গফুটে ঘাস লাগাতে খরচ হয় ২৩.৫০ টাকা<br>
      $\\therefore$ ১৬৫০ বর্গফুটে খরচ হয় = $(১৬৫০ \\times ২৩.৫০) = ৩৮,৭৭৫$ টাকা।<br><br>
      <b>উত্তর:</b> ৩৮,৭৭৫ টাকা।
    `
