    question: "$a = \\sqrt{3} + \\sqrt{2}$ হলে, $a^3 + 3a + 3a^{-1} + a^{-3}$ এর মান কত?",
    solution: `
      দেওয়া আছে, $a = \\sqrt{3} + \\sqrt{2}$<br><br>
      $\\therefore \\frac{1}{a} = \\frac{1}{\\sqrt{3} + \\sqrt{2}} = \\frac{\\sqrt{3} - \\sqrt{2}}{(\\sqrt{3} + \\sqrt{2})(\\sqrt{3} - \\sqrt{2})} = \\frac{\\sqrt{3} - \\sqrt{2}}{3 - 2} = \\sqrt{3} - \\sqrt{2}$<br><br>
      $\\therefore a + \\frac{1}{a} = (\\sqrt{3} + \\sqrt{2}) + (\\sqrt{3} - \\sqrt{2}) = 2\\sqrt{3}$<br><br>
      প্রদত্ত রাশি $= a^3 + 3a + 3a^{-1} + a^{-3}$<br>
      $= a^3 + \\frac{1}{a^3} + 3\\left(a + \\frac{1}{a}\\right)$<br>
      $= \\left(a + \\frac{1}{a}\\right)^3 - 3 \\cdot a \\cdot \\frac{1}{a}\\left(a + \\frac{1}{a}\\right) + 3\\left(a + \\frac{1}{a}\\right)$<br>
      $= \\left(a + \\frac{1}{a}\\right)^3$<br>
      $= (2\\sqrt{3})^3 = 8 \\times 3\\sqrt{3} = 24\\sqrt{3}$<br><br>
      <b>উত্তর:</b> $24\\sqrt{3}$
    `
