    solution: `
      প্রদত্ত রাশি = $\\frac{x^2 + 5x + 6}{x^2 + 3x + 2}$<br><br>
      $= \\frac{x^2 + 3x + 2x + 6}{x^2 + 2x + x + 2}$<br>
      $= \\frac{x(x + 3) + 2(x + 3)}{x(x + 2) + 1(x + 2)}$<br>
      $= \\frac{(x + 3)(x + 2)}{(x + 2)(x + 1)}$<br>
      $= \\frac{x + 3}{x + 1}$<br><br>
      <b>উত্তর:</b> $\\frac{x + 3}{x + 1}$
    `
