    question: "কোন শহরের বর্তমান জনসংখ্যা ৮০ লক্ষ। ঐ শহরের জনসংখ্যা বৃদ্ধির হার প্রতি হাজারে ৩০ হলে, ৩ বছর পর ঐ শহরের জনসংখ্যা কত হবে?",
    solution: `
      এখানে,<br>
      বর্তমান জনসংখ্যা ($P$) = ৮০,০০,০০০<br>
      জনসংখ্যা বৃদ্ধির হার ($r$) = $\\frac{৩০}{১০০০} \\times ১০০\\% = ৩\\% = \\frac{৩}{১০০}$<br>
      সময় ($n$) = ৩ বছর<br><br>
      জনসংখ্যা বৃদ্ধির ক্ষেত্রে চক্রবৃদ্ধি সূত্র প্রযোজ্য:<br>
      $C = P(১ + r)^n$<br>
      $= ৮০,০০,০০০ \\left(১ + \\frac{৩}{১০০}\\right)^৩$<br>
      $= ৮০,০০,০০০ \\times \\left(\\frac{১০৩}{১০০}\\right) \\times \\left(\\frac{১০৩}{১০০}\\right) \\times \\left(\\frac{১০৩}{১০০}\\right)$<br>
      $= ৮ \\times ১০৩ \\times ১০৩ \\times ১০৩$<br>
      $= ৮৭,৪১,৮১৬$<br><br>
      <b>উত্তর:</b> ৮৭,৪১,৮১৬ জন।
    `
