    chapterId: 11, // অধ্যায় ১১: দূরত্ব
    category: "দূরত্ব",
    postType: "অফিস সহায়ক",
    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "১০ মিটার/মিনিট বেগে ৪০ মিটার দীর্ঘ ও ৩০ মিটার প্রস্থ একটি আয়তাকার বাগানের এককোণ থেকে কর্ণ বরাবর হেঁটে অপর প্রান্তে পৌঁছে বাগানের কিনার দিয়ে হেঁটে আগের জায়গায় ফেরত আসতে কত মিনিট সময় লাগবে?",
    solution: `
      দেওয়া আছে, আয়তাকার বাগানের দৈর্ঘ্য $AB = ৪০$ মিটার এবং প্রস্থ $BC = ৩০$ মিটার<br><br>
      কর্ণ বরাবর দূরত্ব $AC = \\sqrt{AB^2 + BC^2}$<br>
      $= \\sqrt{(৪০)^২ + (৩০)^২} = \\sqrt{১৬০০ + ৯০০} = \\sqrt{২৫০০} = ৫০$ মিটার<br><br>
      আমরা জানি, সময় = $\\frac{\\text{দূরত্ব}}{\\text{বেগ}}$<br>
      $\\therefore$ কর্ণ বরাবর যেতে সময় লাগে, $t_1 = \\frac{৫০}{১০} = ৫$ মিনিট<br><br>
      আবার, কিনার দিয়ে হেঁটে ফেরত আসার পথ = $AB + BC = (৪০ + ৩০) = ৭০$ মিটার<br>
      $\\therefore$ ফেরত আসতে সময় লাগে, $t_2 = \\frac{৭০}{১০} = ৭$ মিনিট<br><br>
      $\\therefore$ মোট সময় লাগবে = $t_1 + t_2 = (৫ + ৭) = ১২$ মিনিট।<br><br>
      <b>উত্তর:</b> ১২ মিনিট।
    `
