    question: "একটি ত্রিভুজের তিনটি বাহুর দৈর্ঘ্য ১৩, ১৪ ও ১৫ মিটার। ত্রিভুজটির ক্ষেত্রফল কত?",
    solution: `
      ধরি, ত্রিভুজের বাহুত্রয় যথাক্রমে $a = ১৩$ মিটার, $b = ১৪$ মিটার এবং $c = ১৫$ মিটার<br><br>
      $\\therefore$ অর্ধ-পরিসীমা, $s = \\frac{a + b + c}{২} = \\frac{১৩ + ১৪ + ১৫}{২} = \\frac{৪২}{২} = ২১$ মিটার<br><br>
      আমরা জানি,<br>
      ত্রিভুজের ক্ষেত্রফল = $\\sqrt{s(s - a)(s - b)(s - c)}$<br>
      $= \\sqrt{২১(২১ - ১৩)(২১ - ১৪)(২১ - ১৫)}$ বর্গমিটার<br>
      $= \\sqrt{২১ \\times ৮ \\times ৭ \\times ৬}$ বর্গমিটার<br>
      $= \\sqrt{৭০৫৬}$ বর্গমিটার<br>
      $= ৮৪$ বর্গমিটার।<br><br>
      <b>উত্তর:</b> ৮৪ বর্গমিটার।
    `
