    solution: `
      দেওয়া আছে, আয়তাকার বাড়ির পরিসীমা = ৪৪ গজ<br>
      ঘরের দৈর্ঘ্য = ৩৬ ফুট = $\\frac{৩৬}{৩} = ১২$ গজ [যেহেতু ৩ ফুট = ১ গজ]<br><br>
      আমরা জানি,<br>
      পরিসীমা = $২ \\times (\\text{দৈর্ঘ্য} + \\text{প্রস্থ})$<br>
      $\\Rightarrow ২(১২ + \\text{প্রস্থ}) = ৪৪$<br>
      $\\Rightarrow ১২ + \\text{প্রস্থ} = ২২$<br>
      $\\Rightarrow \\text{প্রস্থ} = ২২ - ১২ = ১০$ গজ<br><br>
      $\\therefore$ ঘরের প্রস্থ = ১০ গজ বা $(১০ \\times ৩) = ৩০$ ফুট।<br><br>
      <b>উত্তর:</b> ১০ গজ (বা ৩০ ফুট)।
    `
