    solution: `
      প্রদত্ত রাশি = $x^3 - 8$<br>
      $= (x)^3 - (2)^3$<br>
      $= (x - 2)(x^2 + 2 \\cdot x + 2^2)$<br>
      $= (x - 2)(x^2 + 2x + 4)$<br><br>
      <b>উত্তর:</b> $(x - 2)(x^2 + 2x + 4)$
    `
