    examYear: "২০২৪",
    question: "যদি মাংসের দাম ২৫% বৃদ্ধি পায়, তবে মাংসের ব্যবহার কী হারে কমালে মাংসের জন্য খরচের কোনো পরিবর্তন হবে না?",
    solution: `
      ধরি, পূর্বে মাংসের মূল্য ছিল = ১০০ টাকা<br><br>
      ২৫% বৃদ্ধিতে বর্তমান মূল্য = $(১০০ + ২৫) = ১২৫$ টাকা<br><br>
      খরচ অপরিবর্তিত রাখতে হলে ১২৫ টাকায় কমাতে হবে ২৫ টাকা<br>
      $\\therefore$ ১ টাকায় কমাতে হবে = $\\frac{২৫}{১২৫}$ টাকা<br>
      $\\therefore$ ১০০ টাকায় কমাতে হবে = $\\frac{২৫ \\times ১০০}{১২৫} = ২০$ টাকা<br><br>
      $\\therefore$ মাংসের ব্যবহার কমাতে হবে ২০%।<br><br>
      <b>উত্তর:</b> ২০%।
    `
