    question: "উৎপাদকে বিশ্লেষণ করুন: $\\frac{1}{2}x^2 - 3x + 4$",
    solution: `
      প্রদত্ত রাশি = $\\frac{1}{2}x^2 - 3x + 4$<br><br>
      $= \\frac{1}{2}(x^2 - 6x + 8)$<br>
      $= \\frac{1}{2}(x^2 - 4x - 2x + 8)$<br>
      $= \\frac{1}{2}\\{x(x - 4) - 2(x - 4)\\}$<br>
      $= \\frac{1}{2}(x - 4)(x - 2)$<br><br>
      <b>উত্তর:</b> $\\frac{1}{2}(x - 4)(x - 2)$
    `
