    postType: "অফিস সহায়ক",
    source: "স্বাস্থ্য ও পরিবার কল্যাণ মন্ত্রণালয়",
    examYear: "২০২৪",
    question: "উৎপাদকে বিশ্লেষণ করুন: $4x^4 - 25x^2 + 36$",
    solution: `
      প্রদত্ত রাশি = $4x^4 - 25x^2 + 36$<br>
      $= 4x^4 - 16x^2 - 9x^2 + 36$<br>
      $= 4x^2(x^2 - 4) - 9(x^2 - 4)$<br>
      $= (x^2 - 4)(4x^2 - 9)$<br>
      $= \\{(x)^2 - (2)^2\\}\\{(2x)^2 - (3)^2\\}$<br>
      $= (x + 2)(x - 2)(2x + 3)(2x - 3)$<br><br>
      <b>উত্তর:</b> $(x + 2)(x - 2)(2x + 3)(2x - 3)$
    `
