    examYear: "২০২৪",
    question: "পিতা ও পুত্রের বর্তমান বয়সের অনুপাত ৭ : ২ এবং ৫ বছর পরে তাদের বয়সের অনুপাত ৮ : ৩ হবে। তাদের বর্তমান বয়স কত?",
    solution: `
      মনে করি,<br>
      পিতার বর্তমান বয়স = $৭x$ বছর<br>
      এবং পুত্রের বর্তমান বয়স = $২x$ বছর<br><br>
      প্রশ্নমতে,<br>
      $\\frac{৭x + ৫}{২x + ৫} = \\frac{৮}{৩}$<br>
      $\\Rightarrow ৩(৭x + ৫) = ৮(২x + ৫)$<br>
      $\\Rightarrow ২১x + ১৫ = ১৬x + ৪০$<br>
      $\\Rightarrow ২১x - ১৬x = ৪০ - ১৫$<br>
      $\\Rightarrow ৫x = ২৫$<br>
      $\\therefore x = ৫$<br><br>
      $\\therefore$ পিতার বর্তমান বয়স = $(৭ \\times ৫) = ৩৫$ বছর<br>
      এবং পুত্রের বর্তমান বয়স = $(২ \\times ৫) = ১০$ বছর।<br><br>
      <b>উত্তর:</b> পিতার বর্তমান বয়স ৩৫ বছর এবং পুত্রের বর্তমান বয়স ১০ বছর।
    `
