    solution: `
      ৩টি লেবুর ক্রয়মূল্য ১ টাকা<br>
      $\\therefore$ ১টি লেবুর ক্রয়মূল্য = $\\frac{১}{৩}$ টাকা<br><br>
      আবার, ২টি লেবুর বিক্রয়মূল্য ১ টাকা<br>
      $\\therefore$ ১টি লেবুর বিক্রয়মূল্য = $\\frac{১}{২}$ টাকা<br><br>
      $\\therefore$ লাভ = $\\left(\\frac{১}{২} - \\frac{১}{৩}\\right) = \\frac{৩ - ২}{৬} = \\frac{১}{৬}$ টাকা<br><br>
      $\\frac{১}{৩}$ টাকায় লাভ হয় $\\frac{১}{৬}$ টাকা<br>
      $\\therefore$ ১ টাকায় লাভ হয় = $\\frac{১}{৬} \\times \\frac{৩}{১}$ টাকা<br>
      $\\therefore$ ১০০ টাকায় লাভ হয় = $\\frac{১ \\times ৩ \\times ১০০}{৬ \\times ১} = ৫০$ টাকা<br><br>
      <b>উত্তর:</b> ৫০%।
    `
