    question: "$x = 7$ এবং $y = 6$ হলে, $16x^2 - 40xy + 25y^2$ এর মান কত?",
    solution: `
      প্রদত্ত রাশি $= 16x^2 - 40xy + 25y^2$<br>
      $= (4x)^2 - 2 \\cdot 4x \\cdot 5y + (5y)^2$<br>
      $= (4x - 5y)^2$<br><br>
      $x$ ও $y$ এর মান বসিয়ে পাই,<br>
      $= (4 \\cdot 7 - 5 \\cdot 6)^2$<br>
      $= (28 - 30)^2$<br>
      $= (-2)^2$<br>
      $= 4$<br><br>
      <b>উত্তর:</b> 4
    `
