    question: "৫ জন তাঁত-শ্রমিক ৫ দিনে ৫টি কাপড় বুনতে পারে। একই ধরনের ৭টি কাপড় বুনতে ৭ জন শ্রমিকের কত দিন লাগবে?",
    solution: `
      ৫ জন শ্রমিক ৫টি কাপড় বুনতে পারে ৫ দিনে<br>
      $\\therefore$ ১ জন শ্রমিক ৫টি কাপড় বুনতে পারে = $(৫ \\times ৫)$ দিনে<br>
      $\\therefore$ ১ জন শ্রমিক ১টি কাপড় বুনতে পারে = $\\frac{৫ \\times ৫}{৫}$ দিনে<br>
      $\\therefore$ ৭ জন শ্রমিক ১টি কাপড় বুনতে পারে = $\\frac{৫ \\times ৫}{৫ \\times ৭}$ দিনে<br>
      $\\therefore$ ৭ জন শ্রমিক ৭টি কাপড় বুনতে পারে = $\\frac{৫ \\times ৫ \\times ৭}{৫ \\times ৭} = ৫$ দিনে।<br><br>
      <b>উত্তর:</b> ৫ দিন।
    `
