    examYear: "২০২৪",
    question: "একটি আয়তাকার ঘরের প্রস্থ তার দৈর্ঘ্যের $\\frac{২}{৩}$ অংশ। ঘরটির পরিসীমা ৪০ মিটার হলে তার ক্ষেত্রফল কত?",
    solution: `
      মনে করি,<br>
      ঘরের দৈর্ঘ্য = $৩x$ মিটার<br>
      $\\therefore$ ঘরের প্রস্থ = $৩x$ এর $\\frac{২}{৩} = ২x$ মিটার<br><br>
      প্রশ্নমতে,<br>
      $২(২x + ৩x) = ৪০$<br>
      $\\Rightarrow ২ \\times ৫x = ৪০$<br>
      $\\Rightarrow ১০x = ৪০$<br>
      $\\therefore x = ৪$<br><br>
      $\\therefore$ দৈর্ঘ্য = $(৩ \\times ৪) = ১২$ মিটার<br>
      এবং প্রস্থ = $(২ \\times ৪) = ৮$ মিটার<br><br>
      $\\therefore$ আয়তাকার ঘরের ক্ষেত্রফল = $(১২ \\times ৮) = ৯৬$ বর্গমিটার।<br><br>
      <b>উত্তর:</b> ৯৬ বর্গমিটার।
    `
