    postType: "অফিস সহায়ক",
    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "একই হার মুনাফায় কোনো আসল ৬ বছরে মুনাফা-আসলে দ্বিগুণ হলে, কত বছরে তা মুনাফা-আসলে তিনগুণ হবে?",
    solution: `
      ধরি, আসল = $p$ টাকা<br>
      $\\therefore$ মুনাফা-আসল = $2p$ টাকা<br>
      $\\therefore$ মুনাফা = $(2p - p) = p$ টাকা<br><br>
      আবার, মুনাফা-আসল তিনগুণ হলে মুনাফা-আসল = $3p$ টাকা<br>
      সেক্ষেত্রে মুনাফা = $(3p - p) = 2p$ টাকা<br><br>
      $p$ টাকা মুনাফা হয় ৬ বছরে<br>
      $\\therefore$ ১ টাকা মুনাফা হয় = $\\frac{৬}{p}$ বছরে<br>
      $\\therefore 2p$ টাকা মুনাফা হয় = $\\frac{৬ \\times 2p}{p} = ১২$ বছরে।<br><br>
      <b>উত্তর:</b> ১২ বছরে।
    `
