    question: "পানি ভর্তি একটি বালতির ওজন ১৫ কেজি। বালতির অর্ধেক পানি ভর্তি হলে তার ওজন ৯.৫ কেজি। খালি বালতির ওজন ও পানির পরিমাণ কত?",
