    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "দুই অঙ্কবিশিষ্ট একটি সংখ্যার অঙ্কদ্বয়ের সমষ্টি ৯, সংখ্যাটির সহিত ৯ যোগ করলে অঙ্কদ্বয় স্থান পরিবর্তন করে। সংখ্যাটি নির্ণয় করুন।",
    solution: `
      মনে করি,<br>
      একক স্থানীয় অঙ্ক = $x$<br>
      এবং দশক স্থানীয় অঙ্ক = $৯ - x$<br><br>
      $\\therefore$ সংখ্যাটি = $১০(৯ - x) + x$<br>
      $= ৯০ - ১০x + x$<br>
      $= ৯০ - ৯x$<br><br>
      অঙ্কদ্বয় স্থান পরিবর্তন করলে নতুন সংখ্যাটি হয় = $১০x + (৯ - x) = ৯x + ৯$<br><br>
      শর্তমতে,<br>
      $৯০ - ৯x + ৯ = ১০x + (৯ - x)$<br>
      $\\Rightarrow ৯৯ - ৯x = ৯x + ৯$<br>
      $\\Rightarrow ৯x + ৯x = ৯৯ - ৯$<br>
      $\\Rightarrow ১৮x = ৯০$<br>
      $\\Rightarrow x = \\frac{৯০}{১৮}$<br>
      $\\therefore x = ৫$<br><br>
      $\\therefore$ সংখ্যাটি = $৯০ - ৯ \\times ৫ = ৯০ - ৪৫ = ৪৫$<br><br>
      <b>উত্তর:</b> ৪৫
    `
