    question: "প্রতি কেজি ইলিশ মাছ ১০০০ টাকা দরে ২০.৭৫ কেজি ইলিশ মাছ ক্রয় করে প্রতি কেজি ১১০০ টাকায় বিক্রয় করলে কত লাভ হবে?",
    solution: `
      ১ কেজি ইলিশের ক্রয়মূল্য ১০০০ টাকা<br>
      $\\therefore$ ২০.৭৫ কেজি ইলিশের ক্রয়মূল্য = $(১০০০ \\times ২০.৭৫) = ২০৭৫০$ টাকা<br><br>
      আবার,<br>
      ১ কেজি ইলিশের বিক্রয়মূল্য ১১০০ টাকা<br>
      $\\therefore$ ২০.৭৫ কেজি ইলিশের বিক্রয়মূল্য = $(১১০০ \\times ২০.৭৫) = ২২৮২৫$ টাকা<br><br>
      $\\therefore$ মোট লাভ = $(২২৮২৫ - ২০৭৫০) = ২০৭৫$ টাকা।<br><br>
      <i>বিকল্প নিয়ম: প্রতি কেজিতে লাভ হয় $(১১০০ - ১০০০) = ১০০$ টাকা। সুতরাং ২০.৭৫ কেজিতে লাভ হয় = $(২০.৭৫ \\times ১০০) = ২০৭৫$ টাকা।</i><br><br>
      <b>উত্তর:</b> ২০৭৫ টাকা।
    `
