    question: "শতকরা বার্ষিক ৪ টাকা হার সুদে কত বছরে ৫০০ টাকার সুদ ৬০ টাকা হবে?",
    solution: `
      এখানে,<br>
      সুদের হার ($r$) = $৪\\% = \\frac{৪}{১০০}$<br>
      আসল ($P$) = ৫০০ টাকা<br>
      সুদ ($I$) = ৬০ টাকা<br>
      সময় ($n$) = ?<br><br>
      আমরা জানি,<br>
      $I = Pnr$<br>
      $\\Rightarrow n = \\frac{I}{Pr}$<br>
      $\\Rightarrow n = \\frac{৬০}{৫০০ \\times \\frac{৪}{১০০}}$<br>
      $\\Rightarrow n = \\frac{৬০}{২০}$<br>
      $\\therefore n = ৩$ বছর<br><br>
      <b>উত্তর:</b> ৩ বছর।
    `
