    source: "নিয়োগ পরীক্ষা",
    examYear: "২০২৪",
    question: "ঘণ্টায় ৭৫ কি.মি. বেগে গমন করলে ১৮০ মিটার দীর্ঘ একটি ট্রেনের ৩২০ মিটার দীর্ঘ একটি প্ল্যাটফর্ম অতিক্রম করতে কত সময় লাগবে?",
    solution: `
      প্ল্যাটফর্মটি অতিক্রম করতে হলে ট্রেনটিকে তার নিজের দৈর্ঘ্য ও প্ল্যাটফর্মের দৈর্ঘ্য অতিক্রম করতে হবে।<br>
      $\\therefore$ মোট অতিক্রান্ত দূরত্ব = $(১৮০ + ৩২০) = ৫০০$ মিটার<br><br>
      আমরা জানি,<br>
      ১ ঘণ্টা = ৩৬০০ সেকেন্ড<br>
      এবং ৭৫ কি.মি. = $(৭৫ \\times ১০০০) = ৭৫০০০$ মিটার<br><br>
      ট্রেনটি ৭৫০০০ মিটার অতিক্রম করে ৩৬০০ সেকেন্ডে<br>
      $\\therefore$ ১ মিটার অতিক্রম করে = $\\frac{৩৬০০}{৭৫০০০}$ সেকেন্ডে<br>
      $\\therefore$ ৫০০ মিটার অতিক্রম করে = $\\frac{৩৬০০ \\times ৫০০}{৭৫০০০} = ২৪$ সেকেন্ডে।<br><br>
      <b>উত্তর:</b> ২৪ সেকেন্ড।
    `
