let currentChapterId = null; 
let activePostFilter = "all";

// ইংরেজি থেকে বাংলা সংখ্যা রূপান্তর হেল্পার
const toBn = n => n.toString().replace(/\d/g, d => "০১২৩৪৫৬৭৮৯"[d]);

// ডাইনামিক ফিল্টার পিল বাটন রেন্ডারিং
function renderFilterPills() {
  const container = document.getElementById("filterPillsContainer");
  if (!container) return;

  const db = (typeof mathDatabase !== 'undefined') ? mathDatabase : [];
  const uniquePosts = [...new Set(db.map(item => item.postType).filter(Boolean))];

  let html = `
    <button class="filter-pill ${activePostFilter === 'all' ? 'active' : ''}" onclick="setPostFilter('all', this)">
      সকল পদ
    </button>
  `;

  uniquePosts.forEach(post => {
    html += `
      <button class="filter-pill ${activePostFilter === post ? 'active' : ''}" onclick="setPostFilter('${post}', this)">
        ${post}
      </button>
    `;
  });

  container.innerHTML = html;
}

// হোমপেজের প্রতিটি অধ্যায়ের কার্ড ও প্রশ্ন সংখ্যা আপডেট
function renderChapterGrid() {
  const container = document.getElementById("gridContainer");
  if (!container) return;

  const db = (typeof mathDatabase !== 'undefined') ? mathDatabase : [];

  // ফিল্টার অনুযায়ী মোট সংখ্যা নির্ধারণ
  const effectiveDb = (activePostFilter === "all") 
    ? db 
    : db.filter(item => item.postType === activePostFilter);

  const countText = document.getElementById("totalQuestionsCountText");
  if (countText) {
    if (activePostFilter === "all") {
      countText.innerText = `মোট সংগৃহীত প্রশ্ন: ${toBn(effectiveDb.length)}টি`;
    } else {
      countText.innerText = `${activePostFilter}: মোট ${toBn(effectiveDb.length)}টি প্রশ্ন`;
    }
  }

  container.innerHTML = chapters.map(chap => {
    // সিলেক্ট করা পদের ওপর ভিত্তি করে প্রতিটি অধ্যায়ের প্রশ্ন গণনা
    const count = effectiveDb.filter(item => item.chapterId === chap.id).length;
    const chapNum = chap.id < 10 ? `০${chap.id}` : toBn(chap.id);

    return `
      <div class="ios-card" onclick="openChapter(${chap.id})" style="${count === 0 ? 'opacity: 0.6;' : ''}">
        <div class="card-glass-symbol" style="--accent-color: ${chap.color};">
          <i class="fa-solid ${chap.icon}"></i>
        </div>
        <div class="card-details">
          <span class="chap-badge">অধ্যায় ${chapNum}</span>
          <h3>${chap.title}</h3>
          <p class="chap-sub">মোট প্রশ্ন: ${toBn(count)}টি</p>
        </div>
        <i class="fa-solid fa-chevron-right chevron-icon"></i>
      </div>
    `;
  }).join('');
}

// অ্যাপ ইনিশিয়ালাইজেশন
function initApp() {
  renderFilterPills();
  renderChapterGrid();
  applyFontSize();
}

// ফিল্টার বাটন হ্যান্ডলার (হোমপেজে হোমপেজের সংখ্যা বদলাবে, অধ্যায়ে প্রশ্নের তালিকা বদলাবে)
function setPostFilter(postKeyword, btn) {
  document.querySelectorAll('.filter-pill').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  activePostFilter = postKeyword;

  if (currentChapterId !== null) {
    // অধ্যায়ের ভেতরে থাকলে ফিল্টার অনুযায়ী প্রশ্ন দেখাবে
    if (currentChapterId === 'all') {
      openAllQuestions();
    } else {
      openChapter(currentChapterId);
    }
  } else {
    // হোমপেজে থাকলে হোমপেজের অধ্যায়গুলোর কার্ডেই আপডেট সংখ্যা দেখাবে
    renderChapterGrid();
  }
}

function openChapter(chapterId) {
  currentChapterId = chapterId;
  const db = (typeof mathDatabase !== 'undefined') ? mathDatabase : [];
  const chap = chapters.find(c => c.id === chapterId);
  
  let filtered = db.filter(item => item.chapterId === chapterId);
  if (activePostFilter !== "all") {
    filtered = filtered.filter(item => item.postType === activePostFilter);
  }
  
  showQuestionView(chap ? chap.title : "অধ্যায়", filtered);
}

function openAllQuestions() {
  currentChapterId = 'all';
  const db = (typeof mathDatabase !== 'undefined') ? mathDatabase : [];
  
  let filtered = db;
  if (activePostFilter !== "all") {
    filtered = filtered.filter(item => item.postType === activePostFilter);
  }
  
  showQuestionView("সকল প্রশ্ন ব্যাংক", filtered);
}

// প্রশ্ন প্রদর্শন: ক্রমিক নং + ডুপ্লিকেট তথ্য + ওয়াটারমার্ক
function showQuestionView(title, questionList) {
  document.getElementById("chapterIndexGrid").style.display = "none";
  const tray = document.getElementById("chapterContentTray");
  tray.style.display = "flex";
  
  document.getElementById("navBackBtn").style.display = "flex";
  document.getElementById("pageMainTitle").innerText = title;

  if (questionList.length === 0) {
    tray.innerHTML = `
      <div style="text-align: center; padding: 40px 10px; color: var(--secondary-text);">
        <i class="fa-regular fa-folder-open" style="font-size: 2.5rem; margin-bottom: 12px;"></i>
        <p>এই ফিল্টারে কোনো প্রশ্ন পাওয়া যায়নি।</p>
      </div>
    `;
    return;
  }

  const seenDuplicateKeys = new Set();

  tray.innerHTML = questionList.map((item, index) => {
    const serialNo = toBn(index + 1);
    const cleanKey = cleanMathText(item.question);
    const matched = duplicateMap[cleanKey] || [];
    const isDuplicate = matched.length > 1;

    let cardClass = "";
    let duplicateNotice = "";
    let watermarkHTML = "";

    if (isDuplicate) {
      if (!seenDuplicateKeys.has(cleanKey)) {
        // ১ম কার্ডে পুনরাবৃত্তির পরিমাণ দেখাবে
        seenDuplicateKeys.add(cleanKey);
        cardClass = "duplicate-primary";
        duplicateNotice = `
          <span class="duplicate-badge" style="background:#fee2e2; color:#b91c1c; border:1px solid #fca5a5; padding:3px 8px; border-radius:6px; font-size:0.75rem; font-weight:700;">
            <i class="fa-solid fa-repeat"></i> এই প্রশ্নটি আরও ${toBn(matched.length - 1)} বার এসেছে
          </span>
        `;
      } else {
        // পরের ডুপ্লিকেটগুলোতে ওয়াটারমার্ক থাকবে
        cardClass = "duplicate-secondary";
        watermarkHTML = `<div class="duplicate-watermark">DUPLICATE</div>`;
      }
    }

    return `
      <div class="question-card ${cardClass}" style="position: relative;">
        ${watermarkHTML}
        <div class="q-meta" style="position: relative; z-index: 1;">
          <div class="badge-wrap">
            <span class="q-tag" style="font-weight: 700;">নং ${serialNo}</span>
            <span class="q-tag">${item.category}</span>
            <span class="q-tag q-source">${item.source} (${item.examYear})</span>
            ${duplicateNotice}
          </div>
          <span class="q-post-badge">${item.postType}</span>
        </div>
        <div class="q-title" style="position: relative; z-index: 1;">${item.question}</div>
        <button class="toggle-sol-btn" style="position: relative; z-index: 1;" onclick="toggleSolution('sol-${item.id}', this)">
          <i class="fa-solid fa-eye"></i> <span>উত্তর দেখুন</span>
        </button>
        <div id="sol-${item.id}" class="solution-drawer" style="position: relative; z-index: 1;">
          ${item.solution}
        </div>
      </div>
    `;
  }).join('');

  if (window.MathJax && MathJax.typesetPromise) {
    MathJax.typesetPromise();
  }
}

function toggleSolution(id, btn) {
  const drawer = document.getElementById(id);
  const isOpen = drawer.classList.contains("open");

  if (isOpen) {
    drawer.classList.remove("open");
    btn.innerHTML = `<i class="fa-solid fa-eye"></i> <span>উত্তর দেখুন</span>`;
  } else {
    drawer.classList.add("open");
    btn.innerHTML = `<i class="fa-solid fa-eye-slash"></i> <span>উত্তর লুকান</span>`;
    if (window.MathJax && MathJax.typesetPromise) {
      MathJax.typesetPromise([drawer]);
    }
  }
}

function goBackToIndex() {
  currentChapterId = null;
  document.getElementById("chapterContentTray").style.display = "none";
  document.getElementById("chapterIndexGrid").style.display = "block";
  document.getElementById("navBackBtn").style.display = "none";
  document.getElementById("pageMainTitle").innerText = "গণিত প্রস্তুতি";
  document.getElementById("spotlightSearch").value = "";
  renderChapterGrid();
}

function onSearchInput(query) {
  const q = query.trim().toLowerCase();
  if (!q) {
    if (currentChapterId !== null) {
      if (currentChapterId === 'all') openAllQuestions();
      else openChapter(currentChapterId);
    } else {
      goBackToIndex();
    }
    return;
  }

  const db = (typeof mathDatabase !== 'undefined') ? mathDatabase : [];
  const results = db.filter(item => 
    (item.question && item.question.toLowerCase().includes(q)) || 
    (item.source && item.source.toLowerCase().includes(q)) ||
    (item.category && item.category.toLowerCase().includes(q)) ||
    (item.postType && item.postType.toLowerCase().includes(q))
  );

  showQuestionView(`অনুসন্ধান: "${query}"`, results);
}

// ফন্ট সাইজ নিয়ন্ত্রণ
let fontStep = localStorage.getItem("mathFontStep") ? parseInt(localStorage.getItem("mathFontStep")) : 0;

function applyFontSize() {
  const baseTitle = 1.05;
  const baseSol = 0.98;
  const stepVal = 0.08;

  const currentTitleSize = (baseTitle + (fontStep * stepVal)).toFixed(2);
  const currentSolSize = (baseSol + (fontStep * stepVal)).toFixed(2);

  document.documentElement.style.setProperty('--q-title-size', `${currentTitleSize}rem`);
  document.documentElement.style.setProperty('--q-sol-size', `${currentSolSize}rem`);
  
  localStorage.setItem("mathFontStep", fontStep);
}

function adjustFontSize(delta) {
  if (fontStep + delta >= -2 && fontStep + delta <= 4) {
    fontStep += delta;
    applyFontSize();
  }
}

// হেডার অটো-হাইড লজিক
let lastScrollY = window.scrollY;
const navbar = document.getElementById("iosNavbar");

window.addEventListener("scroll", () => {
  if (!navbar) return;
  const currentScrollY = window.scrollY;
  if (Math.abs(currentScrollY - lastScrollY) < 10) return;

  if (currentScrollY > lastScrollY && currentScrollY > 70) {
    navbar.classList.add("nav-hidden");
  } else {
    navbar.classList.remove("nav-hidden");
  }
  lastScrollY = currentScrollY;
});

window.onload = initApp;

